#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 998244353;
constexpr int ROOT = 15311432;
constexpr int INVROOT = 469870224;

int bitReverse(int n, int k) {
    int rev = 0;
    for (int i = 0; i < k; ++i) {
        rev = (rev << 1) | (n & 1);
        n >>= 1;
    }
    return rev;
}

long long modPow(long long a, long long p) {
    a %= MOD;
    if (a < 0) a += MOD;
    long long res = 1;
    while (p > 0) {
        if (p & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        p >>= 1;
    }
    return res;
}

long long modInv(int a) {
    return modPow(a, MOD - 2);
}

void numberTheoreticTransform(vector<long long>& coef, int k, bool inverse) {
    int baseRoot = inverse ? INVROOT : ROOT;
    long long root = modPow(baseRoot, modPow(2, 23 - k));
    vector<long long> roots(k);
    roots[k - 1] = root;
    for (int i = k - 1; i > 0; --i) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }

    for (int s = 0; s < k; ++s) {
        int len = 1 << s;
        for (int st = 0; st < (int)coef.size(); st += 2 * len) {
            long long curRoot = 1;
            for (int j = st; j < st + len; ++j) {
                long long t = (curRoot * coef[j + len]) % MOD;
                long long u = coef[j];
                coef[j] = u + t;
                if (coef[j] >= MOD) coef[j] -= MOD;
                coef[j + len] = u - t;
                if (coef[j + len] < 0) coef[j + len] += MOD;
                curRoot = (roots[s] * curRoot) % MOD;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    n /= 2;
    vector<int> nums(m);
    for (int i = 0; i < m; ++i) {
        cin >> nums[i];
    }
    sort(nums.begin(), nums.end());

    int min_size = n * nums.back() + 2;
    int k = 0;
    int size = 1;
    while (size < min_size) {
        size <<= 1;
        ++k;
    }

    vector<long long> a(size, 0);
    for (int i = 0; i < m; ++i) {
        a[bitReverse(nums[i], k)] = 1;
    }

    numberTheoreticTransform(a, k, false);

    for (int i = 0; i < size; ++i) {
        a[i] = modPow(a[i], n);
    }

    vector<long long> temp(size);
    for (int i = 0; i < size; ++i) {
        temp[bitReverse(i, k)] = a[i] % MOD;
    }
    a = move(temp);

    numberTheoreticTransform(a, k, true);

    long long ans = 0;
    for (int i = 0; i < size; ++i) {
        ans = (ans + a[i] * a[i]) % MOD;
    }

    long long multiplier = modInv(size);
    ans = ans * multiplier % MOD * multiplier % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << '\n';

    return 0;
}

